273		}
274		if err := s.Freeze(FreezeInput{
275			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼",
276		}); !errors.Is(err, ErrInvalidDate) {
277			t.Fatalf("缺失冻结日期仍应拒绝: %v", err)
278		}
279		if err := s.Freeze(FreezeInput{
280			ArchiveID: "A-1", FreezeID: "F-1", Reason: "  诉讼  ", FrozenOn: MustParseDate("2025-01-05"),
281		}); err != nil {
282			t.Fatal(err)
283		}
284		h, found, err := s.History("A-1")
285		if err != nil || !found {
286			t.Fatalf("历史应可查: found=%v err=%v", found, err)
287		}
288		if len(h.Freezes) != 1 || h.Freezes[0].Reason != "诉讼" ||
289			!h.Freezes[0].FrozenOn.Equal(MustParseDate("2025-01-05")) {
290			t.Fatalf("原因应去除首尾空白后保存，冻结日期应保留: %+v", h.Freezes)
291		}
292	}
